(12, 3, 1, 4, '[]', '{\"vi\":\"\",\"en\":\"\",\"fr\":\"\",\"ja\":\"\",\"ko\":\"\",\"ru\":\"\",\"th\":\"\",\"id\":\"\",\"de\":\"\",\"hi\":\"\",\"ms\":\"\",\"pt\":\"\",\"km\":\"\",\"nl\":\"\",\"es\":\"\"}', '[[饭店|Fàndiàn]]', '{\"vi\":\"Qu\\u00e1n \\u0103n\\/ Nh\\u00e0 h\\u00e0ng\",\"en\":\"Restaurant\",\"fr\":\"Restaurant\",\"ja\":\"\\u30ec\\u30b9\\u30c8\\u30e9\\u30f3\",\"ko\":\"\\ub808\\uc2a4\\ud1a0\\ub791\",\"ru\":\"\\u0420\\u0435\\u0441\\u0442\\u043e\\u0440\\u0430\\u043d\",\"th\":\"\\u0e23\\u0e49\\u0e32\\u0e19\\u0e2d\\u0e32\\u0e2b\\u0e32\\u0e23\",\"id\":\"Restoran\",\"de\":\"Restaurant\",\"hi\":\"\\u0930\\u0947\\u0938\\u094d\\u091f\\u094b\\u0930\\u0947\\u0902\\u091f\",\"ms\":\"Restoran\",\"pt\":\"Restaurante\",\"km\":\"Restaurant\",\"nl\":\"Restaurant\",\"es\":\"Restaurante\"}', '[]', '[]', 5, '2025-12-22 00:39:54', '2025-12-22 00:39:54'),
(13, 3, 2, 5, '[]', '{\"vi\":\"\",\"en\":\"\",\"fr\":\"\",\"ja\":\"\",\"ko\":\"\",\"ru\":\"\",\"th\":\"\",\"id\":\"\",\"de\":\"\",\"hi\":\"\",\"ms\":\"\",\"pt\":\"\",\"km\":\"\",\"nl\":\"\",\"es\":\"\"}', '[[同学们，|Tóngxuémen,]][[ 再见，|zàijiàn, ]][[我们|wǒmen]][[明天|míngtiān]][[八点| bā diǎn]][[见。|jiàn.]]', '{\"vi\":\"C\\u00e1c em, t\\u1ea1m bi\\u1ec7t, 8 gi\\u1edd ng\\u00e0y mai ch\\u00fang ta g\\u1eb7p l\\u1ea1i.\",\"en\":\"Kids, goodbye, I\'ll see you again tomorrow at 8 o\'clock.\",\"fr\":\"Les enfants, au revoir, je vous retrouve demain \\u00e0 8 heures.\",\"ja\":\"\\u5b50\\u4f9b\\u305f\\u3061\\u3001\\u3055\\u3088\\u3046\\u306a\\u3089\\u3002\\u307e\\u305f\\u660e\\u65e5\\u30018\\u6642\\u306b\\u4f1a\\u3044\\u307e\\u3057\\u3087\\u3046\\u3002\",\"ko\":\"\\uc544\\uc774\\ub4e4\\uc544, \\uc548\\ub155, \\ub0b4\\uc77c 8\\uc2dc\\uc5d0 \\ub2e4\\uc2dc \\ubcf4\\uc790.\",\"ru\":\"\\u0414\\u0435\\u0442\\u0438, \\u0434\\u043e \\u0441\\u0432\\u0438\\u0434\\u0430\\u043d\\u0438\\u044f, \\u0443\\u0432\\u0438\\u0434\\u0438\\u043c\\u0441\\u044f \\u0437\\u0430\\u0432\\u0442\\u0440\\u0430 \\u0432 8 \\u0447\\u0430\\u0441\\u043e\\u0432.\",\"th\":\"\\u0e40\\u0e14\\u0e47\\u0e01\\u0e46 \\u0e25\\u0e32\\u0e01\\u0e48\\u0e2d\\u0e19 \\u0e41\\u0e25\\u0e49\\u0e27\\u0e40\\u0e08\\u0e2d\\u0e01\\u0e31\\u0e19\\u0e1e\\u0e23\\u0e38\\u0e48\\u0e07\\u0e19\\u0e35\\u0e49 8 \\u0e42\\u0e21\\u0e07\\u0e19\\u0e30\",\"id\":\"Anak-anak, selamat tinggal, sampai jumpa lagi besok jam 8.\",\"de\":\"Kinder, auf Wiedersehen, wir sehen uns morgen wieder um 8 Uhr.\",\"hi\":\"\\u092c\\u091a\\u094d\\u091a\\u094b\\u0902, \\u0905\\u0932\\u0935\\u093f\\u0926\\u093e, \\u092e\\u0948\\u0902 \\u0915\\u0932 \\u092b\\u093f\\u0930 8 \\u092c\\u091c\\u0947 \\u092e\\u093f\\u0932\\u0942\\u0902\\u0917\\u093e\\u0964\",\"ms\":\"Kids, goodbye, I\'ll see you again tomorrow at 8 o\'clock.\",\"pt\":\"Crian\\u00e7as, adeus, vejo voc\\u00eas novamente amanh\\u00e3 \\u00e0s 8 horas.\",\"km\":\"Kids, goodbye, I\'ll see you again tomorrow at 8 o\'clock.\",\"nl\":\"Kinderen, tot ziens, ik zie jullie morgen weer om 8 uur.\",\"es\":\"Ni\\u00f1os, adi\\u00f3s, nos vemos de nuevo ma\\u00f1ana a las 8 en punto.\"}', '[]', '[]', 5, '2025-12-22 00:39:54', '2025-12-22 00:39:54'),
(14, 3, 2, 6, '[]', '{\"vi\":\"\",\"en\":\"\",\"fr\":\"\",\"ja\":\"\",\"ko\":\"\",\"ru\":\"\",\"th\":\"\",\"id\":\"\",\"de\":\"\",\"hi\":\"\",\"ms\":\"\",\"pt\":\"\",\"km\":\"\",\"nl\":\"\",\"es\":\"\"}', '[[不客气，喜欢|Búkèqi，xǐhuan]][[吗？|ma?]]', '{\"vi\":\"\\u0110\\u1eebng kh\\u00e1ch s\\u00e1o, c\\u00f3 th\\u00edch kh\\u00f4ng?\",\"en\":\"You\'re welcome, do you like it?\",\"fr\":\"De rien, est-ce que \\u00e7a vous pla\\u00eet ?\",\"ja\":\"\\u3069\\u3046\\u3044\\u305f\\u3057\\u307e\\u3057\\u3066\\u3001\\u6c17\\u306b\\u5165\\u3063\\u3066\\u3044\\u305f\\u3060\\u3051\\u307e\\u3057\\u305f\\u304b\\uff1f\",\"ko\":\"\\ucc9c\\ub9cc\\uc5d0\\uc694, \\ub9c8\\uc74c\\uc5d0 \\ub4dc\\uc2dc\\ub098\\uc694?\",\"ru\":\"\\u041f\\u043e\\u0436\\u0430\\u043b\\u0443\\u0439\\u0441\\u0442\\u0430, \\u0432\\u0430\\u043c \\u043d\\u0440\\u0430\\u0432\\u0438\\u0442\\u0441\\u044f?\",\"th\":\"\\u0e22\\u0e34\\u0e19\\u0e14\\u0e35\\u0e04\\u0e23\\u0e31\\u0e1a \\u0e04\\u0e38\\u0e13\\u0e0a\\u0e2d\\u0e1a\\u0e44\\u0e2b\\u0e21\\u0e04\\u0e23\\u0e31\\u0e1a?\",\"id\":\"Sama-sama, apakah Anda menyukainya?\",\"de\":\"Gern geschehen, gef\\u00e4llt es Ihnen?\",\"hi\":\"\\u0906\\u092a\\u0915\\u093e \\u0938\\u094d\\u0935\\u093e\\u0917\\u0924 \\u0939\\u0948, \\u0915\\u094d\\u092f\\u093e \\u0906\\u092a\\u0915\\u094b \\u092f\\u0939 \\u092a\\u0938\\u0902\\u0926 \\u0906\\u092f\\u093e?\",\"ms\":\"Sama-sama, awak suka tak?\",\"pt\":\"De nada, voc\\u00ea gostou?\",\"km\":\"You\'re welcome, do you like it?\",\"nl\":\"Graag gedaan, vindt u het leuk?\",\"es\":\"De nada, \\u00bfte gusta?\"}', '[]', '[]', 5, '2025-12-22 00:39:54', '2025-12-22 00:39:54'),
(15, 3, 2, 7, '[]', '{\"vi\":\"\",\"en\":\"\",\"fr\":\"\",\"ja\":\"\",\"ko\":\"\",\"ru\":\"\",\"th\":\"\",\"id\":\"\",\"de\":\"\",\"hi\":\"\",\"ms\":\"\",\"pt\":\"\",\"km\":\"\",\"nl\":\"\",\"es\":\"\"}', '[[昨天|Zuótiān]][[下|xià]][[了|le]][[很|hěn]][[大|dà]][[的|de]][[雨|yǔ]][[。|.]]', '{\"vi\":\"H\\u00f4m qua m\\u01b0a r\\u1ea5t to.\",\"en\":\"Yesterday it rained very hard.\",\"fr\":\"Hier, il a plu tr\\u00e8s fort.\",\"ja\":\"\\u6628\\u65e5\\u3001\\u3072\\u3069\\u3044\\u96e8\\u304c\\u964d\\u308a\\u307e\\u3057\\u305f\\u3002\",\"ko\":\"\\uc5b4\\uc81c \\ube44\\uac00 \\uc544\\uc8fc \\ub9ce\\uc774 \\uc654\\uc5b4\\uc694.\",\"ru\":\"\\u0412\\u0447\\u0435\\u0440\\u0430 \\u043e\\u0447\\u0435\\u043d\\u044c \\u0441\\u0438\\u043b\\u044c\\u043d\\u043e \\u0448\\u0451\\u043b \\u0434\\u043e\\u0436\\u0434\\u044c.\",\"th\":\"\\u0e40\\u0e21\\u0e37\\u0e48\\u0e2d\\u0e27\\u0e32\\u0e19\\u0e1d\\u0e19\\u0e15\\u0e01\\u0e2b\\u0e19\\u0e31\\u0e01\\u0e21\\u0e32\\u0e01\",\"id\":\"Kemarin hujan sangat deras.\",\"de\":\"Gestern hat es sehr stark geregnet.\",\"hi\":\"\\u0915\\u0932 \\u092c\\u0939\\u0941\\u0924 \\u091c\\u093c\\u094b\\u0930 \\u0938\\u0947 \\u092c\\u093e\\u0930\\u093f\\u0936 \\u0939\\u0941\\u0908\\u0964\",\"ms\":\"Semalam hujan sangat lebat.\",\"pt\":\"Ontem choveu muito forte.\",\"km\":\"Yesterday it rained very hard.\",\"nl\":\"Gisteren heeft het heel hard geregend.\",\"es\":\"Ayer llovi\\u00f3 muy fuerte.\"}', '[]', '[]', 5, '2025-12-22 00:39:54', '2025-12-22 00:39:54'),
